// LineageLens PR annotation script
// Called by lineagelens-annotate.yml; writes LINEAGELENS_COMMENT to $GITHUB_ENV.

import { appendFileSync } from 'fs';

const API_URL = process.env.LINEAGELENS_API_URL;
const TOKEN = process.env.LINEAGELENS_TOKEN;
const changedFilesRaw = process.env.CHANGED_FILES ?? '';

if (!API_URL || !TOKEN) {
  console.log('LINEAGELENS_API_URL or LINEAGELENS_TOKEN not set — skipping annotation.');
  process.exit(0);
}

const changedFiles = changedFilesRaw
  .split(',')
  .map((f) => f.trim())
  .filter((f) => f.length > 0);

if (changedFiles.length === 0) {
  console.log('No changed files detected — skipping annotation.');
  process.exit(0);
}

console.log(`Fetching LineageLens lineage for ${changedFiles.length} changed file(s)...`);

async function fetchLineage(filePath) {
  const url = new URL('/search', API_URL);
  const res = await fetch(url.toString(), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${TOKEN}`,
    },
    body: JSON.stringify({
      query: '',
      filePath,
      limit: 20,
    }),
  });

  if (!res.ok) {
    console.warn(`LineageLens: search returned ${res.status} for ${filePath}`);
    return [];
  }

  const data = await res.json();
  return Array.isArray(data.results) ? data.results : [];
}

const allResults = [];

for (const filePath of changedFiles) {
  try {
    const results = await fetchLineage(filePath);
    for (const r of results) {
      allResults.push({ ...r, filePath });
    }
  } catch (err) {
    console.warn(`LineageLens: fetch failed for ${filePath}: ${err.message}`);
  }
}

if (allResults.length === 0) {
  console.log('No AI provenance records found for changed files — no comment posted.');
  process.exit(0);
}

// Group by file
const byFile = new Map();
for (const r of allResults) {
  const fp = r.filePath ?? '(unknown)';
  if (!byFile.has(fp)) byFile.set(fp, []);
  byFile.get(fp).push(r);
}

// Build Markdown comment
const lines = [
  '<!-- lineagelens-annotation -->',
  '## 🔍 LineageLens AI Provenance Report',
  '',
  `**${allResults.length} AI-generated block(s)** found across **${byFile.size} file(s)** in this PR.`,
  '',
];

let warningCount = 0;

for (const [filePath, records] of byFile.entries()) {
  const fileName = filePath.split(/[\\/]/).pop() ?? filePath;
  lines.push(`### \`${fileName}\``);
  lines.push(`<details><summary>${records.length} insertion(s) — click to expand</summary>`, '');

  for (const r of records) {
    const model = r.model ?? 'unknown model';
    const ts = r.timestampIso ? new Date(r.timestampIso).toLocaleString('en-US', { timeZoneName: 'short' }) : 'unknown time';
    const uuid = r.uuid ?? '—';
    const snippet = (r.snippet ?? '').trim().slice(0, 300);

    lines.push(`**Block** \`${uuid.slice(0, 8)}…\``);
    lines.push(`- **Model:** ${model}`);
    lines.push(`- **Timestamp:** ${ts}`);
    if (r.score != null) lines.push(`- **Similarity score:** ${Number(r.score).toFixed(3)}`);

    // Check for missing prompt (session warning)
    const hasPrompt = r.record?.promptMessages != null && r.record.promptMessages !== '';
    if (!hasPrompt) {
      lines.push('- ⚠️ **No prompt captured** — this insertion may lack full attribution');
      warningCount++;
    }

    if (snippet) {
      lines.push('```', snippet, '```');
    }

    lines.push('');
  }

  lines.push('</details>', '');
}

if (warningCount > 0) {
  lines.push(
    `> ⚠️ **${warningCount} insertion(s) have incomplete prompt attribution.** ` +
    'Consider running LineageLens in backend mode to capture full prompt context.',
    ''
  );
}

lines.push('---');
lines.push('*Generated by [LineageLens](https://github.com/karnati-praveen/lineagelens) — git blame for AI-generated code.*');

const comment = lines.join('\n');

// Write to GITHUB_ENV for the next step
const envFile = process.env.GITHUB_ENV;
if (envFile) {
  const delimiter = 'LINEAGELENS_EOF';
  appendFileSync(envFile, `LINEAGELENS_COMMENT<<${delimiter}\n${comment}\n${delimiter}\n`);
  console.log('LineageLens comment written to GITHUB_ENV.');
} else {
  // Local test: just print
  console.log('\n--- PR Comment Preview ---\n');
  console.log(comment);
}
